// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MarketRegistry
 * @notice On-chain identity, role-based authorization, asset and meter registry for transactive microgrid.
 */
contract MarketRegistry is AccessControl, Pausable {
    bytes32 public constant MARKET_OPERATOR_ROLE = keccak256("MARKET_OPERATOR_ROLE");
    bytes32 public constant GRID_OPERATOR_ROLE = keccak256("GRID_OPERATOR_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    struct ParticipantInfo {
        string participantId;
        string roleName; // e.g. "PROSUMER", "GENERATOR", "CONSUMER", "STORAGE_OPERATOR"
        bool active;
        uint256 registeredAt;
    }

    struct AssetInfo {
        bytes32 assetId;
        address owner;
        string assetType;
        bytes32 meterIdHash;
        bool renewable;
        bool active;
        uint256 registeredAt;
    }

    struct MeterInfo {
        bytes32 meterIdHash;
        bytes32 assetId;
        address owner;
        bool active;
        uint256 registeredAt;
    }

    mapping(address => ParticipantInfo) public participants;
    mapping(bytes32 => AssetInfo) public assets;
    mapping(bytes32 => MeterInfo) public meters;

    event ParticipantRegistered(address indexed wallet, string participantId, string roleName);
    event ParticipantDeactivated(address indexed wallet);
    event AssetRegistered(bytes32 indexed assetId, address indexed owner, string assetType, bytes32 meterIdHash, bool renewable);
    event AssetDeactivated(bytes32 indexed assetId);
    event MeterRegistered(bytes32 indexed meterIdHash, bytes32 indexed assetId, address indexed owner);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MARKET_OPERATOR_ROLE, admin);
        _grantRole(GRID_OPERATOR_ROLE, admin);
        _grantRole(ORACLE_ROLE, admin);
    }

    function isAuthorizedOracle(address account) external view returns (bool) {
        return hasRole(ORACLE_ROLE, account);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    function registerParticipant(
        address wallet,
        string calldata participantId,
        string calldata roleName
    ) external onlyRole(MARKET_OPERATOR_ROLE) whenNotPaused {
        require(wallet != address(0), "Invalid wallet address");
        participants[wallet] = ParticipantInfo({
            participantId: participantId,
            roleName: roleName,
            active: true,
            registeredAt: block.timestamp
        });
        emit ParticipantRegistered(wallet, participantId, roleName);
    }

    function deactivateParticipant(address wallet) external onlyRole(MARKET_OPERATOR_ROLE) {
        require(participants[wallet].active, "Participant not active");
        participants[wallet].active = false;
        emit ParticipantDeactivated(wallet);
    }

    function registerAsset(
        bytes32 assetId,
        address owner,
        string calldata assetType,
        bytes32 meterIdHash,
        bool renewable
    ) external onlyRole(MARKET_OPERATOR_ROLE) whenNotPaused {
        require(owner != address(0), "Invalid owner");
        require(assetId != bytes32(0), "Invalid asset ID");
        assets[assetId] = AssetInfo({
            assetId: assetId,
            owner: owner,
            assetType: assetType,
            meterIdHash: meterIdHash,
            renewable: renewable,
            active: true,
            registeredAt: block.timestamp
        });
        emit AssetRegistered(assetId, owner, assetType, meterIdHash, renewable);
    }

    function deactivateAsset(bytes32 assetId) external onlyRole(MARKET_OPERATOR_ROLE) {
        require(assets[assetId].active, "Asset not active");
        assets[assetId].active = false;
        emit AssetDeactivated(assetId);
    }

    function registerMeter(
        bytes32 meterIdHash,
        bytes32 assetId,
        address owner
    ) external onlyRole(MARKET_OPERATOR_ROLE) whenNotPaused {
        require(meterIdHash != bytes32(0), "Invalid meter ID hash");
        meters[meterIdHash] = MeterInfo({
            meterIdHash: meterIdHash,
            assetId: assetId,
            owner: owner,
            active: true,
            registeredAt: block.timestamp
        });
        emit MeterRegistered(meterIdHash, assetId, owner);
    }

    function isParticipantActive(address wallet) external view returns (bool) {
        return participants[wallet].active;
    }

    function getAssetOwner(bytes32 assetId) external view returns (address) {
        require(assets[assetId].active, "Asset inactive or unknown");
        return assets[assetId].owner;
    }

    function isMeterAuthorized(bytes32 meterIdHash, bytes32 assetId) external view returns (bool) {
        return meters[meterIdHash].active && meters[meterIdHash].assetId == assetId;
    }
}

contracts/RenewableEnergyCertificate.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title RenewableEnergyCertificate (EAC)
 * @notice Issues, transfers, splits, and retires verified Energy Attribute Certificates.
 * Enforces cryptographic generation uniqueness and prevents double-counting.
 */
contract RenewableEnergyCertificate is AccessControl, Pausable {
    bytes32 public constant ISSUER_ROLE = keccak256("ISSUER_ROLE");

    enum CertificateStatus {
        ISSUED,
        TRANSFERRED,
        RETIRED,
        REVOKED
    }

    struct Certificate {
        bytes32 certificateId;
        bytes32 generatorAssetId;
        string sourceType;
        uint256 quantityWh;
        uint256 generationStart;
        uint256 generationEnd;
        bytes32 meterEvidenceHash;
        address owner;
        CertificateStatus status;
        uint256 issuedAt;
        uint256 retiredAt;
        string retirementPurpose;
    }

    mapping(bytes32 => Certificate) public certificates;
    mapping(bytes32 => bool) public generationEvidenceUsed; // Prevents duplicate EAC issuance

    uint256 public totalRenewableWhIssued;
    uint256 public totalRenewableWhRetired;

    event CertificateIssued(
        bytes32 indexed certificateId,
        address indexed owner,
        bytes32 indexed generatorAssetId,
        string sourceType,
        uint256 quantityWh,
        bytes32 meterEvidenceHash
    );
    event CertificateTransferred(bytes32 indexed certificateId, address indexed from, address indexed to);
    event CertificateSplit(bytes32 indexed originalId, bytes32 indexed newId1, bytes32 indexed newId2, uint256 qty1, uint256 qty2);
    event CertificateRetired(bytes32 indexed certificateId, address indexed owner, uint256 quantityWh, string purpose);
    event CertificateRevoked(bytes32 indexed certificateId, string reason);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ISSUER_ROLE, admin);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    function issueCertificate(
        bytes32 certificateId,
        address recipient,
        bytes32 generatorAssetId,
        string calldata sourceType,
        uint256 quantityWh,
        uint256 generationStart,
        uint256 generationEnd,
        bytes32 meterEvidenceHash
    ) external onlyRole(ISSUER_ROLE) whenNotPaused {
        require(certificateId != bytes32(0), "Invalid certificate ID");
        require(recipient != address(0), "Invalid recipient");
        require(quantityWh > 0, "Quantity must be positive");
        require(generationEnd >= generationStart, "Invalid generation window");
        require(meterEvidenceHash != bytes32(0), "Missing meter evidence hash");
        require(!generationEvidenceUsed[meterEvidenceHash], "Duplicate issuance: evidence already certified");
        require(certificates[certificateId].issuedAt == 0, "Certificate already exists");

        generationEvidenceUsed[meterEvidenceHash] = true;

        certificates[certificateId] = Certificate({
            certificateId: certificateId,
            generatorAssetId: generatorAssetId,
            sourceType: sourceType,
            quantityWh: quantityWh,
            generationStart: generationStart,
            generationEnd: generationEnd,
            meterEvidenceHash: meterEvidenceHash,
            owner: recipient,
            status: CertificateStatus.ISSUED,
            issuedAt: block.timestamp,
            retiredAt: 0,
            retirementPurpose: ""
        });

        totalRenewableWhIssued += quantityWh;

        emit CertificateIssued(certificateId, recipient, generatorAssetId, sourceType, quantityWh, meterEvidenceHash);
    }

    function transferCertificate(bytes32 certificateId, address to) external whenNotPaused {
        Certificate storage c = certificates[certificateId];
        require(c.issuedAt > 0, "Certificate not found");
        require(msg.sender == c.owner, "Only current owner can transfer");
        require(to != address(0) && to != c.owner, "Invalid recipient");
        require(c.status != CertificateStatus.RETIRED, "Retired certificate cannot be transferred");
        require(c.status != CertificateStatus.REVOKED, "Revoked certificate cannot be transferred");

        address from = c.owner;
        c.owner = to;
        c.status = CertificateStatus.TRANSFERRED;

        emit CertificateTransferred(certificateId, from, to);
    }

    function retireCertificate(bytes32 certificateId, string calldata purpose) external whenNotPaused {
        Certificate storage c = certificates[certificateId];
        require(c.issuedAt > 0, "Certificate not found");
        require(msg.sender == c.owner, "Only owner can retire certificate");
        require(c.status != CertificateStatus.RETIRED, "Certificate already retired");
        require(c.status != CertificateStatus.REVOKED, "Cannot retire revoked certificate");

        c.status = CertificateStatus.RETIRED;
        c.retiredAt = block.timestamp;
        c.retirementPurpose = purpose;
        totalRenewableWhRetired += c.quantityWh;

        emit CertificateRetired(certificateId, msg.sender, c.quantityWh, purpose);
    }

    function splitCertificate(
        bytes32 originalId,
        bytes32 newId1,
        bytes32 newId2,
        uint256 splitWh1,
        uint256 splitWh2,
        address recipient1,
        address recipient2
    ) external whenNotPaused {
        Certificate storage orig = certificates[originalId];
        require(orig.issuedAt > 0, "Original certificate not found");
        require(msg.sender == orig.owner, "Only owner can split");
        require(orig.status != CertificateStatus.RETIRED && orig.status != CertificateStatus.REVOKED, "Cannot split retired/revoked");
        require(splitWh1 > 0 && splitWh2 > 0, "Split quantities must be positive");
        require(splitWh1 + splitWh2 == orig.quantityWh, "Conservation failed: sum must equal original quantity");
        require(certificates[newId1].issuedAt == 0 && certificates[newId2].issuedAt == 0, "New certificate IDs must be fresh");

        // Mark original as retired/split
        orig.status = CertificateStatus.RETIRED;
        orig.retiredAt = block.timestamp;
        orig.retirementPurpose = "Split into child certificates";

        // Create child 1
        certificates[newId1] = Certificate({
            certificateId: newId1,
            generatorAssetId: orig.generatorAssetId,
            sourceType: orig.sourceType,
            quantityWh: splitWh1,
            generationStart: orig.generationStart,
            generationEnd: orig.generationEnd,
            meterEvidenceHash: orig.meterEvidenceHash,
            owner: recipient1,
            status: CertificateStatus.ISSUED,
            issuedAt: block.timestamp,
            retiredAt: 0,
            retirementPurpose: ""
        });

        // Create child 2
        certificates[newId2] = Certificate({
            certificateId: newId2,
            generatorAssetId: orig.generatorAssetId,
            sourceType: orig.sourceType,
            quantityWh: splitWh2,
            generationStart: orig.generationStart,
            generationEnd: orig.generationEnd,
            meterEvidenceHash: orig.meterEvidenceHash,
            owner: recipient2,
            status: CertificateStatus.ISSUED,
            issuedAt: block.timestamp,
            retiredAt: 0,
            retirementPurpose: ""
        });

        emit CertificateSplit(originalId, newId1, newId2, splitWh1, splitWh2);
    }

    function revokeCertificate(bytes32 certificateId, string calldata reason) external onlyRole(DEFAULT_ADMIN_ROLE) {
        Certificate storage c = certificates[certificateId];
        require(c.issuedAt > 0, "Certificate not found");
        c.status = CertificateStatus.REVOKED;
        emit CertificateRevoked(certificateId, reason);
    }

    function ownerOf(bytes32 certificateId) external view returns (address) {
        require(certificates[certificateId].issuedAt > 0, "Certificate not found");
        return certificates[certificateId].owner;
    }

    function isRetired(bytes32 certificateId) external view returns (bool) {
        require(certificates[certificateId].issuedAt > 0, "Certificate not found");
        return certificates[certificateId].status == CertificateStatus.RETIRED;
    }

    function getCertificate(bytes32 certificateId) external view returns (Certificate memory) {
        require(certificates[certificateId].issuedAt > 0, "Certificate not found");
        return certificates[certificateId];
    }
}

contracts/ReserveSettlement.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./MarketRegistry.sol";

/**
 * @title ReserveSettlement
 * @notice On-chain economic settlement for microgrid operating reserves
 * (FCR, Spinning, Non-Spinning, Replacement) integrating Phase 2 reserve market.
 */
contract ReserveSettlement is ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    enum ReserveServiceType {
        FREQUENCY_CONTAINMENT, // <2s
        SPINNING_RESERVE,      // <30s
        NON_SPINNING,          // <300s
        REPLACEMENT            // <1800s
    }

    enum ReserveStatus {
        COMMITTED,
        ACTIVATED,
        DELIVERY_REPORTED,
        SETTLED,
        FAILED,
        CANCELLED
    }

    struct ReserveCommitment {
        bytes32 commitmentId;
        address provider;
        bytes32 assetId;
        ReserveServiceType serviceType;
        uint256 capacityKw;
        uint256 responseDeadlineSeconds;
        uint256 availabilityPayment;    // GUSD wei for standing by
        uint256 activationPricePerKwh;  // GUSD wei per kWh when activated
        uint256 windowStart;
        uint256 windowEnd;
        uint256 collateralAmount;       // Provider collateral locked
        ReserveStatus status;
        // Activation details
        uint256 requestedKw;
        uint256 activationDurationSeconds;
        uint256 activatedAt;
        // Delivery details
        uint256 deliveredKw;
        uint256 actualResponseSeconds;
        bytes32 evidenceHash;
    }

    IERC20 public immutable settlementToken;
    MarketRegistry public immutable registry;

    // Commitment storage
    mapping(bytes32 => ReserveCommitment) public commitments;
    bytes32[] public commitmentList;

    // Configurable penalty rate basis points (e.g., 2000 = 20% penalty of collateral/shortfall)
    uint256 public nonPerformancePenaltyBps = 2500; // 25% default

    // Events
    event ReserveCommitted(
        bytes32 indexed commitmentId,
        address indexed provider,
        bytes32 indexed assetId,
        ReserveServiceType serviceType,
        uint256 capacityKw,
        uint256 availabilityPayment,
        uint256 collateralAmount
    );

    event ReserveActivated(
        bytes32 indexed commitmentId,
        uint256 requestedKw,
        uint256 durationSeconds,
        uint256 timestamp
    );

    event ReserveDeliveryReported(
        bytes32 indexed commitmentId,
        uint256 deliveredKw,
        uint256 actualResponseSeconds,
        bytes32 evidenceHash
    );

    event ReserveSettled(
        bytes32 indexed commitmentId,
        address indexed provider,
        uint256 availabilityPaid,
        uint256 activationPaid,
        uint256 penaltyDeducted,
        ReserveStatus finalStatus
    );

    event ReserveFailed(bytes32 indexed commitmentId, string reason);
    event PenaltyRateUpdated(uint256 oldBps, uint256 newBps);

    modifier onlyOperator() {
        require(
            registry.hasRole(registry.MARKET_OPERATOR_ROLE(), msg.sender) ||
            registry.hasRole(registry.GRID_OPERATOR_ROLE(), msg.sender),
            "Caller is not authorized operator"
        );
        _;
    }

    modifier onlyOracle() {
        require(registry.isAuthorizedOracle(msg.sender), "Caller is not authorized oracle");
        _;
    }

    constructor(address _settlementToken, address _registry) {
        require(_settlementToken != address(0), "Invalid token address");
        require(_registry != address(0), "Invalid registry address");
        settlementToken = IERC20(_settlementToken);
        registry = MarketRegistry(_registry);
    }

    function pause() external onlyOperator {
        _pause();
    }

    function unpause() external onlyOperator {
        _unpause();
    }

    function setPenaltyRateBps(uint256 _newBps) external onlyOperator {
        require(_newBps <= 10000, "Penalty cannot exceed 100%");
        emit PenaltyRateUpdated(nonPerformancePenaltyBps, _newBps);
        nonPerformancePenaltyBps = _newBps;
    }

    /**
     * @notice Create and fund a reserve commitment.
     * Escrows availability payment from operator/payer and locks collateral from provider.
     */
    function createReserveCommitment(
        bytes32 commitmentId,
        address provider,
        bytes32 assetId,
        ReserveServiceType serviceType,
        uint256 capacityKw,
        uint256 responseDeadlineSeconds,
        uint256 availabilityPayment,
        uint256 activationPricePerKwh,
        uint256 windowStart,
        uint256 windowEnd,
        uint256 collateralAmount
    ) external onlyOperator nonReentrant whenNotPaused {
        require(commitmentId != bytes32(0), "Invalid commitment ID");
        require(commitments[commitmentId].commitmentId == bytes32(0), "Commitment already exists");
        require(provider != address(0), "Invalid provider address");
        require(capacityKw > 0, "Capacity must be > 0");
        require(windowEnd > windowStart, "Invalid time window");

        ReserveCommitment storage c = commitments[commitmentId];
        c.commitmentId = commitmentId;
        c.provider = provider;
        c.assetId = assetId;
        c.serviceType = serviceType;
        c.capacityKw = capacityKw;
        c.responseDeadlineSeconds = responseDeadlineSeconds;
        c.availabilityPayment = availabilityPayment;
        c.activationPricePerKwh = activationPricePerKwh;
        c.windowStart = windowStart;
        c.windowEnd = windowEnd;
        c.collateralAmount = collateralAmount;
        c.status = ReserveStatus.COMMITTED;

        commitmentList.push(commitmentId);

        // Lock collateral from provider if required
        if (collateralAmount > 0) {
            settlementToken.safeTransferFrom(provider, address(this), collateralAmount);
        }

        // Lock availability payment from operator pool
        if (availabilityPayment > 0) {
            settlementToken.safeTransferFrom(msg.sender, address(this), availabilityPayment);
        }

        emit ReserveCommitted(
            commitmentId,
            provider,
            assetId,
            serviceType,
            capacityKw,
            availabilityPayment,
            collateralAmount
        );
    }

    /**
     * @notice Trigger activation of committed reserve capacity during contingency/balancing.
     */
    function activateReserve(
        bytes32 commitmentId,
        uint256 requestedKw,
        uint256 durationSeconds
    ) external onlyOperator whenNotPaused {
        ReserveCommitment storage c = commitments[commitmentId];
        require(c.status == ReserveStatus.COMMITTED, "Commitment not in COMMITTED state");
        require(requestedKw > 0 && requestedKw <= c.capacityKw, "Invalid requested capacity");
        require(block.timestamp >= c.windowStart && block.timestamp <= c.windowEnd, "Outside window");

        c.status = ReserveStatus.ACTIVATED;
        c.requestedKw = requestedKw;
        c.activationDurationSeconds = durationSeconds;
        c.activatedAt = block.timestamp;

        emit ReserveActivated(commitmentId, requestedKw, durationSeconds, block.timestamp);
    }

    /**
     * @notice Delivery oracle reports measured response.
     */
    function reportReserveDelivery(
        bytes32 commitmentId,
        uint256 deliveredKw,
        uint256 actualResponseSeconds,
        bytes32 evidenceHash
    ) external onlyOracle whenNotPaused {
        ReserveCommitment storage c = commitments[commitmentId];
        require(c.status == ReserveStatus.ACTIVATED, "Reserve not activated");
        require(evidenceHash != bytes32(0), "Invalid evidence hash");

        c.deliveredKw = deliveredKw;
        c.actualResponseSeconds = actualResponseSeconds;
        c.evidenceHash = evidenceHash;
        c.status = ReserveStatus.DELIVERY_REPORTED;

        emit ReserveDeliveryReported(commitmentId, deliveredKw, actualResponseSeconds, evidenceHash);
    }

    /**
     * @notice Settle reserve commitment: availability payment + energy activation payment or penalties.
     */
    function settleReserve(bytes32 commitmentId) external nonReentrant whenNotPaused {
        ReserveCommitment storage c = commitments[commitmentId];
        require(
            c.status == ReserveStatus.COMMITTED || c.status == ReserveStatus.DELIVERY_REPORTED,
            "Cannot settle in current state"
        );

        uint256 availabilityToPay = c.availabilityPayment;
        uint256 activationToPay = 0;
        uint256 penalty = 0;
        ReserveStatus finalStatus = ReserveStatus.SETTLED;

        if (c.status == ReserveStatus.COMMITTED) {
            // Case 1: Never activated, standby period completed successfully
            require(block.timestamp >= c.windowEnd, "Commitment window not yet ended");
            // Return collateral and pay full availability payment to provider
            c.status = ReserveStatus.SETTLED;
        } else {
            // Case 2: Activated and delivery reported
            bool responseOnTime = c.actualResponseSeconds <= c.responseDeadlineSeconds;
            uint256 deliveredKw = c.deliveredKw;
            uint256 requestedKw = c.requestedKw;

            if (!responseOnTime || deliveredKw < (requestedKw * 80 / 100)) {
                // Non-performance failure: under-delivered by >20% or late
                finalStatus = ReserveStatus.FAILED;
                penalty = (c.collateralAmount * nonPerformancePenaltyBps) / 10000;
                availabilityToPay = 0; // Forfeit availability payment
            } else {
                // Performance acceptable: calculate energy activation payment
                // energyKwh = (min(deliveredKw, requestedKw) * durationSeconds) / 3600
                uint256 energyKwh = (deliveredKw * c.activationDurationSeconds) / 3600;
                activationToPay = energyKwh * c.activationPricePerKwh;
            }
            c.status = finalStatus;
        }

        // If reserve was activated, settler (operator) funds the activation energy charge
        if (activationToPay > 0) {
            settlementToken.safeTransferFrom(msg.sender, address(this), activationToPay);
        }

        // Payout to provider: availability + activation + remaining collateral
        uint256 providerPayout = availabilityToPay + activationToPay + (c.collateralAmount - penalty);
        if (providerPayout > 0) {
            settlementToken.safeTransfer(c.provider, providerPayout);
        }

        // Penalty / unused availability returned to operator/system
        uint256 operatorRefund = (c.availabilityPayment - availabilityToPay) + penalty;
        if (operatorRefund > 0) {
            settlementToken.safeTransfer(msg.sender, operatorRefund);
        }

        emit ReserveSettled(
            commitmentId,
            c.provider,
            availabilityToPay,
            activationToPay,
            penalty,
            finalStatus
        );
    }

    function getCommitment(bytes32 commitmentId) external view returns (ReserveCommitment memory) {
        return commitments[commitmentId];
    }
}

